"""Deep Research Capability — record constructors & validators (Round 1).

Wraps the inherited Research OS kernel authorities so the 13 Deep Research
Capability records are constructed and validated consistently with the kernel,
without duplicating vocabulary or authority.

Key design points (per TASK.md Round 1 / Qwen Round 1 lesson — canonical
outputs beat hand-edits, and re-use-not-duplicate):

* The 13 JSON Schemas are GENERATED by ``generate_schemas.py``; this module
  loads and validates against them. Never hand-edit the emitted JSON.
* The executor-observation contract delegates the prohibited-key / required
  field enforcement to ``research_os.executor_contract.validate_return`` — the
  kernel is the single authority for "an executor may never self-approve, mark
  complete, or raise a claim ceiling".
* Every record field is explicitly classified by ORIGIN so downstream code and
  tests can prove the executor never writes an owner/GPT-adjudicated field and
  never smuggles a prohibited key.

Run from the repository root:
    python3 tools/deep_research/records.py   # self smoke-test
"""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any

REPO_ROOT = Path(__file__).resolve().parents[2]
SCHEMA_DIR = REPO_ROOT / "schemas" / "deep-research"

# Field-origin categories -----------------------------------------------------
DETERMINISTIC = "deterministic"          # kernel / OS computed (ids, shas, facts derived by OS)
EXECUTOR_PROPOSED = "executor_proposed"  # written by the executor under contract
OWNER_ADJUDICATED = "owner_adjudicated"  # requires an explicit GPT/owner decision
KERNEL_ENUM = "kernel_enum"              # value drawn from a kernel vocabulary
PROHIBITED = "prohibited"                # executor is forbidden from ever writing this

_SCHEMA_CACHE: dict[str, dict] = {}


def load_schema(name: str) -> dict:
    """Load a generated deep-research schema by record name (fail-closed)."""
    if name in _SCHEMA_CACHE:
        return _SCHEMA_CACHE[name]
    path = SCHEMA_DIR / f"{name}.schema.json"
    if not path.exists():
        raise FileNotFoundError(
            f"schema '{name}' not found at {path}; run generate_schemas.py first"
        )
    with open(path, "r", encoding="utf-8") as fh:
        data = json.load(fh)
    _SCHEMA_CACHE[name] = data
    return data


def validate_record(name: str, obj: Any) -> Any:
    """Validate ``obj`` against the generated schema for ``name`` (fail-closed).

    Raises ``ValueError`` with collected messages on any schema violation.
    Unknown/extra properties are rejected (additionalProperties: False).
    """
    if not isinstance(obj, dict):
        raise ValueError(f"record '{name}' must be a JSON object")
    schema = load_schema(name)
    try:
        import jsonschema  # type: ignore
    except Exception:
        # jsonschema missing — at minimum enforce required fields structurally.
        missing = [f for f in schema.get("required", []) if f not in obj]
        if missing:
            raise ValueError(f"record '{name}' missing required fields: {missing}")
        return obj
    validator = jsonschema.Draft202012Validator(schema)
    errors = [f"{list(e.path)}: {e.message}" for e in validator.iter_errors(obj)]
    if errors:
        raise ValueError(
            f"record '{name}' failed schema validation:\n  " + "\n  ".join(errors)
        )
    return obj


# Executor-observation: delegate to the kernel contract ------------------------
def validate_executor_observation(obj: Any) -> Any:
    """Enforce the Research OS executor-return contract, then the deep-research
    structural schema. The kernel is the authority for prohibited keys and the
    seven required return fields; the deep-research schema adds observation_id /
    action_id and the fail-closed ``if/then`` rules."""
    if not isinstance(obj, dict):
        raise ValueError("executor-observation must be a JSON object")
    sys.path.insert(0, str(REPO_ROOT / "tools"))
    from research_os.executor_contract import validate_return  # type: ignore

    # Kernel enforces required return fields + prohibited keys (self_approved,
    # mark_episode_complete, claim_ceiling). strict_schema=False here because the
    # deep-research observation carries extra keys the kernel schema omits.
    validate_return(obj, strict_schema=False)
    return validate_record("executor-observation", obj)


