def field_origin(record: str, field: str) -> str:
    """Return the ORIGIN category for ``field`` of ``record``.

    Falls back to EXECUTOR_PROPOSED for unlisted-but-schema-known fields (they
    are executor-writable by default), and PROHIBITED only where explicitly
    declared. Raises ValueError for fields absent from the schema entirely.
    """
    schema = load_schema(record)
    if field not in schema.get("properties", {}):
        raise ValueError(f"field '{field}' is not part of record '{record}'")
    return _ORIGIN.get(record, {}).get(field, EXECUTOR_PROPOSED)


def list_records() -> list[str]:
    return sorted(
        p.stem.replace(".schema", "")
        for p in SCHEMA_DIR.glob("*.schema.json")
    )


# Constructors ----------------------------------------------------------------
