def make_queue_item(**o: Any) -> dict:
    return make_record("research-queue-item", **o)


def make_campaign(**o: Any) -> dict:
    return make_record("research-campaign", **o)


def _smoke() -> None:
    """Self smoke-test: build every record once; assert origin invariants."""
    for name in list_records():
        make_record(name)
    # Invariant: an executor-observation must never carry an owner-adjudicated or
    # prohibited field as a legitimately writable field (prohibited keys are the
    # only exceptions, and they must be classified PROHIBITED, not writable).
    for fld, cat in _ORIGIN.get("executor-observation", {}).items():
        assert cat in (DETERMINISTIC, EXECUTOR_PROPOSED, PROHIBITED), (
            f"executor-observation field {fld} has unexpected origin {cat}"
        )
    # claim_ceiling in claim-evidence-record is owner-adjudicated, never executor.
    assert field_origin("claim-evidence-record", "claim_ceiling") == OWNER_ADJUDICATED
    print(f"records.py smoke OK: {len(list_records())} records constructible")


if __name__ == "__main__":
    _smoke()
